<?/*********************************** 게시판 관리 *************************************///게시판 디비 만들기function makeBoard($boardid){	// 테이블 중복검사(게시판용 테이블이 아닌 일반용에서)	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	## $Table_exist = mysql_list_tables($GLOBALS["_conf_db"]["main_db"]["db"]); ## PHP 7 사용불가	$sql = "SHOW TABLES like '".$tblid."'";	//echo $sql;	$Table_exist = mysqli_query($GLOBALS['dblink'], $sql);	if (!$Table_exist) {		jsMsg("테이블 선택 실패");		//jsHistory("-1") ;	}	$Table_Num = mysqli_num_rows($Table_exist);	if($Table_Num>0){		jsMsg("이미 사용중인 테이블 입니다.");		jsHistory("-1") ;		exit();	}	/*	for ($i=0;$i<$Table_Num;$i++) {		for ($j=0;$j<$Table_Etc;$j++) {			$Table_Name = mysqli_result($Table_exist,$i,$j);			if ($tblid==$Table_Name) {				jsMsg("이미 사용중인 테이블 입니다.");				jsHistory("-1") ;			}		}	}	*/	//게시판 정보 테이블에 입력	$sql = "INSERT INTO ".$GLOBALS["_conf_tbl"]["board_info"]." set 		boardid='$boardid',		wdate=now()	";	//echo $sql;	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$total = mysqli_affected_rows($GLOBALS['dblink']);	if($total > 0){		//게시판 테이블 생성		$sql = "CREATE TABLE $tblid (			idx int(10) unsigned NOT NULL auto_increment COMMENT '일련번호',			no tinyint(1) unsigned DEFAULT '1' NOT NULL COMMENT '정렬용 번호',			main int(10) unsigned DEFAULT '99999999' NOT NULL COMMENT '원글번호',			sub tinyint(3) unsigned DEFAULT '0' NOT NULL COMMENT '답글위치',			depth tinyint(3) unsigned DEFAULT '0' NOT NULL COMMENT '답글깊이',			w_user varchar(100) COMMENT '글쓴사람',			r_user varchar(100) COMMENT '답글쓴사람',			name varchar(50) COMMENT '작성자명',			pass varchar(255) COMMENT '비밀번호',			homepage varchar(255) COMMENT '홈페이지',			tel varchar(100) COMMENT '연락처',			fax varchar(100) COMMENT '팩스',			email varchar(255) COMMENT '이메일',			subject varchar(255) COMMENT '제목',			contents mediumtext COMMENT '내용',			usereplyemail enum('Y','N') NOT NULL default 'N' COMMENT '답변시 메일받음',			usehtml enum('Y','N') NOT NULL default 'N' COMMENT 'HTML 사용',			category varchar(50) COMMENT '게시판 카테고리',			uselock enum('Y','N') NOT NULL default 'N' COMMENT '글잠금',			hit int(10) COMMENT '조회수',			b_sort int(10) DEFAULT '0' NOT NULL COMMENT '순서',			etc_1 varchar(255) COMMENT '여분필드1',			etc_2 varchar(255) COMMENT '여분필드2',			etc_3 varchar(255) COMMENT '여분필드3',			etc_4 varchar(255) COMMENT '여분필드4',			etc_5 TEXT COMMENT '여분필드5',			ip varchar(24) COMMENT 'IP주소',			schedule_date DATE NOT NULL DEFAULT '0000-00-00' COMMENT '스케줄일정',			wdate DATETIME NOT NULL DEFAULT '0000-00-00 00:00:00' COMMENT '작성일',			PRIMARY KEY (idx),			KEY no (no, main, sub)		)";		//echo $sql;		//exit;		$rs = mysqli_query($GLOBALS['dblink'], $sql);		if($rs){			return true;		}else{			//위에서 입력한 게시판 정보 삭제			$sql = "delete from ".$GLOBALS["_conf_tbl"]["board_info"]." where boardid='$boardid' ";			mysqli_query($GLOBALS['dblink'], $sql);			return false;		}	}else{		jsMsg("게시판 정보 테이블 입력실패");		return false;	}}## 산업평가 복사function copyBoardEva($pidx){	$tbl = $GLOBALS["_SITE"]["BOARD_PREWORD"]."evaluation";	//main 번호 가져오기	$q_main = mysqli_query($GLOBALS['dblink'],"select min(main) from $tbl ");	$c_main = @mysqli_result($q_main,0,0);	if(!$c_main){		$main='99999999';	}else{		$main=$c_main-1;	}	$sql = "INSERT INTO ".$tbl." (NO,main,sub,depth,w_user,r_user,name,pass,homepage,tel,fax,email,subject,contents,usereplyemail,usehtml,category,uselock,hit,b_sort,etc_1,etc_2,etc_3,etc_4,etc_5,ip,schedule_date,wdate,date_y,accept1_sdate,accept1_edate,accept2_sdate,accept2_edate,evaluation1_sdate,evaluation1_edate,publication1_date,publication1_time,evaluation2_sdate,evaluation2_edate,publication2_date,publication2_time,price,account_info,reply_date,pay1_f_edate,pay1_f_time,pay1_l_sdate,pay1_l_edate,pay1_l_time,pay2_f_sdate,pay2_f_edate,pay2_f_time,pay2_l_sdate,pay2_l_edate,pay2_l_time,item_name,item_note,item_title,item_show,cont_text01,cont_text02,cont_text03,cont_text04,cont_text05,cont_text06,cont_text07,cont_text08,cont_text09,cont_text10,cont_text11,cont_text12,cont_text13,cont_text14,cont_text15,cont_text16,cont_text17,cont_text18,cont_text19,cont_text20,img1_title,img2_title,img3_title,img4_title,img1_note,img2_note,img3_note,img4_note,site1_subject,site1_link,site2_subject,site2_link,site3_subject,site3_link,site4_subject,site4_link,view_1,view_2,view_3)	SELECT NO,'".$main."' AS main,sub,depth,w_user,r_user,name,pass,homepage,tel,fax,email,subject,contents,usereplyemail,usehtml,category,uselock,hit,b_sort,etc_1,etc_2,etc_3,etc_4,etc_5,ip,schedule_date,wdate,date_y,accept1_sdate,accept1_edate,accept2_sdate,accept2_edate,evaluation1_sdate,evaluation1_edate,publication1_date,publication1_time,evaluation2_sdate,evaluation2_edate,publication2_date,publication2_time,price,account_info,reply_date,pay1_f_edate,pay1_f_time,pay1_l_sdate,pay1_l_edate,pay1_l_time,pay2_f_sdate,pay2_f_edate,pay2_f_time,pay2_l_sdate,pay2_l_edate,pay2_l_time,item_name,item_note,item_title,item_show,cont_text01,cont_text02,cont_text03,cont_text04,cont_text05,cont_text06,cont_text07,cont_text08,cont_text09,cont_text10,cont_text11,cont_text12,cont_text13,cont_text14,cont_text15,cont_text16,cont_text17,cont_text18,cont_text19,cont_text20,img1_title,img2_title,img3_title,img4_title,img1_note,img2_note,img3_note,img4_note,site1_subject,site1_link,site2_subject,site2_link,site3_subject,site3_link,site4_subject,site4_link,view_1,view_2,view_3 FROM ".$tbl." WHERE idx=".$pidx;	//echo $sql;	$rs = mysqli_query($GLOBALS['dblink'], $sql);	if($rs){		return true;	}else{		return false;	}}function editBoard($arrData){	//게시판 데이터 수정	$sql = "UPDATE ".$GLOBALS["_conf_tbl"]["board_info"]." SET		boardname='".$arrData['f_boardname']."', 		skin='".$arrData['f_skin']."', 		scale='".$arrData['f_scale']."', 		pagescale='".$arrData['f_pagescale']."', 		widthscale='".$arrData['f_widthscale']."', 		thumwidth='".$arrData['f_thumwidth']."', 		newmark='".$arrData['f_newmark']."', 		besthit='".$arrData['f_besthit']."', 		subjectcut='".$arrData['f_subjectcut']."', 		useadminonly='".$arrData['f_useadminonly']."', 		useintranet='".$arrData['f_intranet']."', 		usepds='".$arrData['f_usepds']."', 		usereply='".$arrData['f_usereply']."', 		usememo='".$arrData['f_usememo']."', 		uselock='".$arrData['f_uselock']."', 		readlevel='".$arrData['f_readlevel']."', 		writelevel='".$arrData['f_writelevel']."', 		replylevel='".$arrData['f_replylevel']."', 		listlevel='".$arrData['f_listlevel']."', 		category='".str_replace(" ","",$arrData['f_category'])."', 		header='".$arrData['f_header']."', 		footer='".$arrData['f_footer']."' 		WHERE idx='".$arrData['idx']."' 	";	// echo $sql;	$rs = mysqli_query($GLOBALS['dblink'], $sql);	if($rs){		return true;	}else{		return false;	}}function deleteBoard($idx){	//게시판 정보 가져오기	$arrInfo = getArticleInfo($GLOBALS["_conf_tbl"]["board_info"], $idx);	if($arrInfo["total"] > 0){		$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $arrInfo["list"][0]["boardid"];		//게시판 정보 삭제		$sql = "DELETE FROM ".$GLOBALS["_conf_tbl"]["board_info"]." WHERE idx='".$idx."'	";		//echo $sql;		$rs1 = mysqli_query($GLOBALS['dblink'], $sql);		//게시판 테이블 삭제		$sql = "DROP TABLE ".$tblid;		$rs2 = mysqli_query($GLOBALS['dblink'], $sql);		//파일 테이블 정보 삭제		$sql = "DELETE FROM ".$GLOBALS["_conf_tbl"]["board_files"]." WHERE boardid='".$arrInfo["list"][0]["boardid"]."'	";		$rs3 = mysqli_query($GLOBALS['dblink'], $sql);		//댓글 삭제		mysqli_query($GLOBALS['dblink'], "DELETE FROM ".$GLOBALS["_conf_tbl"]["comment"]." WHERE boardid='".$arrInfo["list"][0]["boardid"]."'");		if($rs1 && $rs2 &&$rs3){			return true;		}else{			return false;		}	}else{		return false;	}}// 헤더부분만 변경function editBoardHeader($boardid){	//게시판 데이터 수정	$sql = "UPDATE ".$GLOBALS["_conf_tbl"]["board_info"]." SET		header='".mysqli_real_escape_string($GLOBALS["dblink"],$_POST['header'])."'		WHERE boardid='".mysqli_real_escape_string($GLOBALS["dblink"],$_POST['boardid'])."' 	";	// echo $sql;	$rs = mysqli_query($GLOBALS['dblink'], $sql);	if($rs){		return true;	}else{		return false;	}}/*********************************** 게시판 관리 *************************************//*********************************** 게시물관련 *************************************///게시판 설정정보 가져오기function getBoardInfo($tbl, $boardid){	$sql  = "SELECT * ";	$sql .= "FROM ".$GLOBALS["_conf_tbl"]["board_info"]." ";	$sql .= "WHERE boardid = '$boardid' ";//echo $sql;	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$total_rs = mysqli_num_rows($rs);	if($total_rs > 0){		$list['total'] = $total_rs;		for($i=0; $i < $total_rs; $i++){			$list['list'][$i] = mysqli_fetch_assoc($rs);		}	}else{		$list['total'] = 0;	}	return $list;}//게시물 가져오기 - 파일 제외function getBoardListBase($boardid, $category, $sw="", $sk="", $scale, $offset=0, $subQuery="", $orderby=""){	//게시판 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	//카테고리가 있을경우	if($category !=""){		$que_category = " and category='$category' ";	}	if($_GET['sk2']){		switch($_GET['sw2']){			case("n") :				$q_limit = "and name like '%".$_GET['sk2']."%'";				break;			case("h") :				$q_limit = "and homepage like '%".$_GET['sk2']."%'";				break;			case("e2") :				$q_limit = "and etc_2 like '%".$_GET['sk2']."%'";				break;		}	}	//검색키워드가 있을경우	if($sk !=""){		switch($sw){			case("idx") :				$que_where = "and idx in (".$sk.") ";				break;			case("n") :				$que_where = "and name like '%$sk%'";				break;			case("s") :				$que_where = "and subject like '%$sk%'";				break;			case("shipping") :				$que_where = "and subject like '%$sk%'";				break;			case("h") :				$que_where = "and homepage like '%$sk%'";				break;			case("hg") :				$que_where = "and homepage='$sk'";				break;			case("e1") :				$que_where = "and etc_1 = '$sk'";				break;			case("e2") :				$que_where = "and etc_2 = '$sk'";				break;			case("e3") :				$que_where = "and etc_3 like '%$sk%'";				break;			case("e4") :				$que_where = "and etc_4 = '$sk'";				break;			case("c") :				$que_where = "and contents like '%$sk%'";				break;			case("u_id") :				$que_where = "and w_user = '$sk'";				break;			case("r_id") :				$que_where = "and r_user = '$sk'";				break;			case("ko_company") :				$que_where = "and ko_company like '%$sk%'";				break;			case("schedule_date") :				$que_where = "and schedule_date like '%$sk%'";				break;			case("a") :			default :				$que_where = "and (name like '%$sk%' or subject like '%$sk%' or contents like '%$sk%' or w_user like '%$sk%' or etc_3 like '%$sk%')";		}	}	if($_REQUEST['sk2'] && $sw=="shipping"){		$que_where .= " AND contents like '%".$_REQUEST['sk2']."%' ";	}	if($_REQUEST['scsdate']){		$que_where .= " AND schedule_date >= '".mysqli_real_escape_string($GLOBALS['dblink'], $_REQUEST['scsdate'])."' ";	}	if($_REQUEST['scedate']){		$que_where .= " AND schedule_date <= '".mysqli_real_escape_string($GLOBALS['dblink'], $_REQUEST['scedate'])."' ";	}	if($subQuery){		$que_where .= $subQuery;	}	//카운트	$sql = "select count(idx) from $tblid WHERE 1=1 $q_limit $que_where $que_category ";//	echo $sql;	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$row = mysqli_fetch_row($rs);	$total_rs = $row[0];	//목록	$sql  = "SELECT * ";	$sql .= "FROM $tblid ";	//$sql .= "WHERE no='1' $q_limit $que_where $que_category ";	$sql .= "WHERE 1=1 $q_limit $que_where $que_category ";//	echo $sql;	if($total_rs > 0){		$list['total'] = $total_rs;		// 페이지 네비게이션 오프셋 지정.		if(!$offset){			$offset=0;		}else{			$offset=$offset;		}		// offset 이 전체 게시물수보다 작을때 offset 을 전체게시물 - 페이지당 보여줄 글 수로 offset 설정		if($total_rs<=$offset){			$offset = $total_rs - $scale;		}		if($boardid == "audio") {	# 오디오 도슨트			if($scale > 0){				$sql .= " order by hit asc, idx asc limit $offset,$scale ";			}else{				$sql .= " order by hit asc, idx asc";			}		}else if($boardid == "place") {	# 순서가 필요한 테이블			if($scale > 0){				$sql .= " order by b_sort desc,idx asc limit $offset,$scale ";			}else{				$sql .= " order by b_sort desc,idx asc";			}		}else if($orderby){			if($scale > 0){				$sql .= $orderby." limit $offset,$scale ";			}else{				$sql .= $orderby;			}		}else if($boardid == "business" || $boardid == "notice" || $boardid == "subcontractor" || $boardid == "office") {	#			if($scale > 0){				$sql .= " order by schedule_date desc,idx desc limit $offset,$scale ";			}else{				$sql .= " order by schedule_date desc,idx desc";			}		}else{			if($scale > 0){				$sql .= " order by idx desc limit $offset,$scale ";			}else{				$sql .= " order by idx desc";			}		}		$rs = mysqli_query($GLOBALS['dblink'], $sql);		//	echo $sql;		// offset 을 이용한 limit 가 적용된 갯수		$total = mysqli_num_rows($rs);		$list['list']['total'] = $total;		// 페이지 네비게이션 오프셋 지정.		for($i=0; $i < $total; $i++){			$list['list'][$i] = mysqli_fetch_assoc($rs);		}	}else{		$list['total'] = 0;	}	return $list;}//게시물 가져오기 - 스케줄 형식function getBoardListSchedule($boardid, $s_date, $e_date){	//게시판 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	//목록	$sql  = "SELECT * ";	$sql .= "FROM $tblid ";	$sql .= "WHERE schedule_date >= '$s_date' AND  schedule_date <= '$e_date' ";	$sql .= " order by no, main, sub ";	//echo $sql;	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$total = mysqli_num_rows($rs);	$list['list']['total'] = $total;	for($i=0; $i < $total; $i++){		$row = mysqli_fetch_assoc($rs);		$list['list'][$row['schedule_date']][] = $row;	}	return $list;}//게시물 가져오기 - 스케줄 형식function getBoardScheduleCnt($boardid, $s_date, $e_date, $subject, $idx){	//게시판 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	//목록	$sql  = "SELECT * ";	$sql .= "FROM $tblid ";	$sql .= "WHERE schedule_date >= '$s_date' AND  schedule_date <= '$e_date' AND subject = '$subject' ";	if($idx){		$sql .= " AND idx != $idx ";	}	$sql .= " order by no, main, sub ";	//echo $sql;	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$total = mysqli_num_rows($rs);	$list['list']['total'] = $total;	for($i=0; $i < $total; $i++){		$row = mysqli_fetch_assoc($rs);		$list['list'][$row[schedule_date]][] = $row;	}	return $list;}//게시물 가져오기 - 스케줄 형식function getBoardListScheduleBooking($boardid, $s_date, $e_date, $adminid=""){	//게시판 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	//목록	$sql  = "SELECT * ";	$sql .= "FROM $tblid ";	$sql .= "WHERE schedule_date >= '$s_date' AND  schedule_date <= '$e_date' AND length(etc_2)>0 ";	if($adminid){		$sql .= " AND admin_idx = '$adminid' ";	}	$sql .= " order by no, main, sub ";	//echo $sql;	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$total = mysqli_num_rows($rs);	$list['list']['total'] = $total;	for($i=0; $i < $total; $i++){		$row = mysqli_fetch_assoc($rs);		$list['list'][$row['schedule_date']][] = $row;	}	return $list;}//게시물 가져오기 - 스케줄 형식function getBoardListScheduleCalculate($boardid, $s_date, $e_date, $adminid=""){	//게시판 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	//목록	$sql  = "SELECT * ";	$sql .= "FROM $tblid ";	$sql .= "WHERE schedule_date >= '$s_date' AND  schedule_date <= '$e_date' AND length(etc_2)>0 ";	if($adminid){		$sql .= " AND admin_idx = '$adminid' ";	}	$sql .= " order by no, main, sub ";	//echo $sql;	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$total = mysqli_num_rows($rs);	$list['list']['total'] = $total;	for($i=0; $i < $total; $i++){		$row = mysqli_fetch_assoc($rs);		$list['list'][$row['schedule_date']][] = $row;	}	return $list;}//게시물 가져오기 - 파일 포함function getBoardListBaseNFile($boardid, $category, $sw="", $sk="", $scale, $offset=0, $subQuery="", $reply="", $orderBy=""){	//게시판 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	$q_limit	= "";	$que_where	= "";	$que_category	= "";	$que_etc	= "";	//일대일문의(request) 게시판 : 자기 게시물만 호출	if($boardid == "request" && $reply=="re") {		$que_where .= " and w_user='".$_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["MEMBER"]["ID"]."' 