rd_files"];	//목록	$sql  = " SELECT A.*, B.idx AS f_idx, B.boardid, B.b_idx, B.ori_name, B.re_name, B.type, B.size ";	if ($boardid == "equ_applicants_cart"){		$sql .= " FROM $tblid A LEFT JOIN ".$fileDB." B ON B.boardid='equ' AND A.equ_idx=B.b_idx";	}else{		$sql .= " FROM $tblid A LEFT JOIN ".$fileDB." B ON B.boardid='$boardid' AND A.idx=B.b_idx";	}	$sql .= " WHERE 1=1 $q_limit $que_where $que_category $que_etc group by A.idx";	//echo $sql;	//조회 부분	//echo "echo:"; print_r($sql); echo "<br>" ;	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$total_rs = mysqli_num_rows($rs);	if($total_rs > 0){		$list['total'] = $total_rs;		// 페이지 네비게이션 오프셋 지정.		if(!$offset){			$offset=0;		}else{			$offset=$offset;		}		// offset 이 전체 게시물수보다 작을때 offset 을 전체게시물 - 페이지당 보여줄 글 수로 offset 설정		if($total_rs<=$offset){			$offset = $total_rs - $scale;		}		//scale 0 으로 지정시에는 전체 가져옴		if($orderBy){			$sql .= $orderBy;		}else if($_GET['rdnm'] && $_GET['rdsc']){			if($scale > 0){				$sql .= " order by ".$_GET['rdnm']." ".$_GET['rdsc']." limit $offset,$scale ";			}else{				$sql .= " order by ".$_GET['rdnm']." ".$_GET['rdsc']." ";			}		}else{			if($boardid == "after") {	# 상품리뷰				if($_GET['order']=="et4"){					if($scale > 0){						$sql .= " order by etc_4 desc,idx desc limit $offset,$scale ";					}else{						$sql .= " order by etc_4 desc,idx desc";					}				}else{					if($scale > 0){						$sql .= " order by idx desc limit $offset,$scale ";					}else{						$sql .= " order by idx desc";					}				}			}else if($boardid == "notice" ) {	# 공지사항				if($scale > 0){					$sql .= " order by no asc,idx desc limit $offset,$scale ";				}else{					$sql .= " order by no asc,idx desc";				}			}else if($boardid == "equ" || $boardid == "place" || $boardid == "mainbanner" || $boardid == "clogo" || $boardid == "trend" || $boardid == "KCAeducation" || $boardid == "KCAsafety" || $boardid == "KCAfood" || $boardid == "KCApress" || $boardid == "KCApolicy" || $boardid == "KCAreport" || $boardid == "KCAnews"  || $boardid == "KCAculture"  || $boardid == "KCAawards"  || $boardid == "KCAcompany" ) {	# 순서가 필요한 테이블				if($scale > 0){					$sql .= " order by b_sort desc,idx desc limit $offset,$scale ";				}else{					$sql .= " order by b_sort desc,idx desc";				}			}else if($boardid == "notice" || $boardid == "technical" || $boardid == "cardnews" || $boardid == "leaflet" || $boardid == "sgnews" || $boardid == "story" || $boardid == "event") {	# 날짜순				if($scale > 0){					$sql .= " order by schedule_date desc,idx desc limit $offset,$scale ";				}else{					$sql .= " order by schedule_date desc,idx desc";				}			}else if($boardid == "history") {	# 연혁				if($scale > 0){					$sql .= " order by schedule_date desc,idx asc limit $offset,$scale ";				}else{					$sql .= " order by schedule_date desc,idx asc";				}			}else if($boardid == "qna111") {	# 1:1 문의				if($scale > 0){					$sql .= " order by etc_1 asc,idx desc limit $offset,$scale ";				}else{					$sql .= " order by etc_1 asc,idx desc";				}			}else if($boardid == "droneimage" && $reply) {	# 사용자				if($scale > 0){					$sql .= $reply." limit $offset,$scale ";				}else{					$sql .= $reply;				}			}else if($boardid == "sub_evaluation" && $reply == "user"){				if($scale > 0){					$sql .= " order by no asc, b_sort asc, idx desc limit $offset,$scale ";				}else{					$sql .= " order by no asc, b_sort asc, idx desc";				}			}else if($reply == "user"){				if($scale > 0){					$sql .= " order by no asc, b_sort asc, idx desc limit $offset,$scale ";				}else{					$sql .= " order by no asc, b_sort asc, idx desc";				}			}else{				if($scale > 0){					$sql .= " order by no asc, idx desc limit $offset,$scale ";				}else{					$sql .= " order by no asc, idx desc";				}			}		}			//echo $sql;		$rs = mysqli_query($GLOBALS['dblink'], $sql);		//echo $sql;		//exit();		// offset 을 이용한 limit 가 적용된 갯수		$total = mysqli_num_rows($rs);		$list['list']['total'] = $total;		// 페이지 네비게이션 오프셋 지정.		for($i=0; $i < $total; $i++){			$list['list'][$i] = mysqli_fetch_assoc($rs);		}	}else{		$list['total'] = 0;	}	return $list;}//게시물 가져오기 - 파일 포함function getBoardListBaseNAllFile($boardid, $category, $sw="", $sk="", $scale, $offset=0, $page="", $reply=""){	//게시판 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	$q_limit	= "";	$que_where	= "";	$que_category	= "";	$que_etc	= "";	//카테고리가 있을경우	if($category !=""){		$que_category = " and A.category='$category' ";	}	if(isset($_GET['etc_1'])){		$que_etc .= " and A.etc_1='".$_GET['etc_1']."' ";	}	//검색키워드가 있을경우	if($sk !=""){		switch($sw){			case("n") :				$que_where = "and A.name like '%$sk%'";				break;			case("order") :				$que_where = "and (A.etc_1 like '%$sk%' or A.subject like '%$sk%' ) ";				break;			case("s") :				$que_where = "and A.subject like '%$sk%'";				break;			case("idx") :				$que_where = "and A.idx = '$sk'";				break;			case("sd") :				$que_where = "and A.schedule_date like '%$sk%'";				break;			case("h") :				$que_where = "and A.homepage like '%$sk%'";				break;			case("e") :				$que_where = "and A.etc_1 = '$sk'";				break;			case("e1l") :				$que_where = "and A.etc_1 like '%$sk%'";				break;			case("e2l") :				$que_where = "and A.etc_2 like '%$sk%'";				break;			case("e3l") :				$que_where = "and A.etc_3 like '%$sk%'";				break;			case("e5l") :				$que_where = "and A.etc_5 like '%$sk%'";				break;			case("cate") :				$que_where = "and A.category = '$sk'";				break;			case("e4") :				$que_where = "and A.etc_4 = '$sk'";				break;			case("userid") :				$que_where = "and A.w_user = '$sk'";				break;			case("search") :				$que_where = "and A.tel = '". $_SESSION["MEMBER"]["HP"] ."' and A.email = '". $_SESSION["MEMBER"]["EMAIL"] ."' ";				break;			case("c") :				$que_where = "and A.contents like '%$sk%'";				break;			case("a") :			default :				$que_where = "and (A.name like '%$sk%' or A.subject like '%$sk%' or A.contents like '%$sk%')";		}		// 검색시 영역을 분할하여 검색=> 속도향상용		$sql = "select count(A.idx) as cnt from $tblid A";		$rs = mysqli_query($GLOBALS['dblink'], $sql);		$row = mysqli_fetch_assoc($rs);		$q_total = $row['cnt'];		$q_start = $q_total - 10000; // 최근 10000건만 검색		if($q_total>10000){			$q_limit = " A.idx between " . $q_start . " and " . $q_total . " ";		}		// 검색시 영역을 분할하여 검색=> 속도향상용	}	if($_REQUEST['s_date']){		$que_where .= " AND A.wdate >= '".mysqli_real_escape_string($GLOBALS['dblink'], $_REQUEST['s_date'])." 00:00:00' ";	}	if($_REQUEST['e_date']){		$que_where .= " AND A.wdate <= '".mysqli_real_escape_string($GLOBALS['dblink'], $_REQUEST['e_date'])." 23:59:59' ";	}	//echo $reply;	//exit();	//카운트	//$sql = "select count(A.idx) from $tblid A WHERE A.no='1' $q_limit $que_where $que_category ";	$sql = "select count(A.idx) from ".$tblid." A WHERE 1=1 ".$q_limit." ".$que_where." ".$que_category." ".$que_etc;	//echo $sql;	//exit;	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$row = mysqli_fetch_row($rs);	$total_rs = $row[0];	//=========================================================	// mysql 4.1 부터 적용되는 쿼리	//=========================================================	// 20100624	// 그림의 정렬순서를 입력된 순서로 하고자 할경우 실행	// 4.1 부터 서브쿼리가 적용되므로 이하일경우	// 일반 group by 쿼리를 그냥 사용한다	//=========================================================	//if (mysqli_get_server_info()>4.1){	//	$sub_query=" ( SELECT *  FROM ".$GLOBALS["_conf_tbl"]["board_files"]." ORDER BY idx ASC ) ";	//}else{	$sub_query= $GLOBALS["_conf_tbl"]["board_files"];	//}	//목록	$sql  = " SELECT A.*, B.idx AS f_idx, B.boardid, B.b_idx, B.ori_name, B.re_name, B.type, B.size ";	$sql .= " FROM $tblid A LEFT JOIN ".$sub_query." B ON B.boardid='$boardid' AND A.equ_idx=B.b_idx";	$sql .= "  AND LEFT(B.re_name,1) = 'l' ";	/*if($boardid != "brochure" && $boardid != "brochureeng"){	$sql .= "  AND B.ext IN('jpg','gif','png')";	}	if($boardid == "promot" || $boardid == "promoteng"){	$sql .= "  AND LEFT(B.re_name,1) = 'l' ";	}*/	$sql .= " WHERE 1=1 $q_limit $que_where $que_category $que_etc group by A.idx";	//echo $sql;	//echo "//".$offset."//".$scale;	if($total_rs > 0){		$list['total'] = $total_rs;		// 페이지 네비게이션 오프셋 지정.		if(!$offset){			$offset=0;		}else{			$offset=$offset;		}		// offset 이 전체 게시물수보다 작을때 offset 을 전체게시물 - 페이지당 보여줄 글 수로 offset 설정		if($total_rs<=$offset){			$offset = $total_rs - $scale;		}		//scale 0 으로 지정시에는 전체 가져옴		if($boardid == "after") {	# 상품리뷰			if($_GET['order']=="et4"){				if($scale > 0){					$sql .= " order by etc_4 desc,idx desc limit $offset,$scale ";				}else{					$sql .= " order by etc_4 desc,idx desc";				}			}else{				if($scale > 0){					$sql .= " order by idx desc limit $offset,$scale ";				}else{					$sql .= " order by idx desc";				}			}		}else{			if($scale > 0){				$sql .= " order by A.no, A.main, A.sub, A.wdate desc limit $offset,$scale ";			}else{				$sql .= " order by A.no, A.main, A.sub, A.wdate desc ";			}		}		//echo $sql;		$rs = mysqli_query($GLOBALS['dblink'], $sql);		//echo $sql;		//exit();		// offset 을 이용한 limit 가 적용된 갯수		$total = mysqli_num_rows($rs);		$list['list']['total'] = $total;		// 페이지 네비게이션 오프셋 지정.		for($i=0; $i < $total; $i++){			$list['list'][$i] = mysqli_fetch_assoc($rs);			################################### files ST			$sql  = "SELECT * FROM ".$GLOBALS["_conf_tbl"]["board_files"]." WHERE boardid = '$boardid' AND b_idx = '".$list['list'][$i]['idx']."' order by idx";			$file_rs = mysqli_query($GLOBALS['dblink'], $sql);			$total_file = mysqli_num_rows($file_rs);			if($total_file > 0){				$list['list'][$i]['total_files'] = $total_file;				for($j=0; $j < $total_file; $j++){					$list['list'][$i]['files'][$j] = mysqli_fetch_assoc($file_rs);				}			}else{				$list['list'][$i]['total_files'] = 0;			}		}	}else{		$list['total'] = 0;	}	return $list;}//게시물 가져오기 - 댓글카운트 포함function getBoardListBaseNMemoCnt($boardid, $category, $sw="", $sk="", $scale, $offset=0){	//게시판 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	$tbl_comment = $GLOBALS["_conf_tbl"]["comment"];	if($boardid == "after" && $_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["MEMBER"]["ID"]) {		//	$que_where .= " or (w_user='".$_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["MEMBER"]["ID"]."') ";	}	//카테고리가 있을경우	if($category !=""){		$que_category = " and category='$category' ";	}	if($_GET[user_id]) {		$que_where .= "and (w_user = '".$_GET[user_id]."' or schedule_date='0000-00-00') ";	} else if($boardid == "after" && $_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["ADMIN"]["GRADE"]!="ROOT") {		$que_where .= " and schedule_date!='0000-00-00'";	}	//검색키워드가 있을경우	if($sk !=""){		switch($sw){			case("n") :				$que_where .= "and name like '%$sk%'";				break;			case("s") :				$que_where .= "and subject like '%$sk%'";				break;			case("c") :				$que_where .= "and contents like '%$sk%'";				break;			case("e") :				$que_where .= "and etc_1 = '$sk'";				break;			case("sp") :				$que_where = "and schedule_date = '0000-00-00'";				break;			case("a") :			default :				$que_where .= "and (name like '%$sk%' or subject like '%$sk%' or contents like '%$sk%')";		}		// 검색시 영역을 분할하여 검색=> 속도향상용		$sql = "select count(idx) as cnt from $tblid ";		$rs = mysqli_query($GLOBALS['dblink'], $sql);		$row = mysqli_fetch_assoc($rs);		$q_total = $row[cnt];		$q_start = $q_total - 10000; // 최근 10000건만 검색		if($q_total>10000){			$q_limit = " idx between " . $q_start . " and " . $q_total . " ";		}		// 검색시 영역을 분할하여 검색=> 속도향상용	}	//카운트	//$sql = "select count(idx) from $tblid WHERE no='1' $q_limit $que_where $que_category $que_catcode ";	$sql = "select count(idx) from $tblid WHERE 1=1 $q_limit $que_where $que_category $que_catcode ";	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$row = mysqli_fetch_row($rs);	$total_rs = $row[0];	//목록	$sql  = "SELECT * ";	$sql .= "FROM $tblid ";	//$sql .= "WHERE no='1' $q_limit $que_where $que_category $que_catcode ";	$sql .= "WHERE 1=1 $q_limit $que_where $que_category $que_catcode ";	if($total_rs > 0){		$list['total'] = $total_rs;		// 페이지 네비게이션 오프셋 지정.		if(!$offset){			$offset=0;		}else{			$offset=$offset;		}		// offset 이 전체 게시물수보다 작을때 offset 을 전체게시물 - 페이지당 보여줄 글 수로 offset 설정		if($total_rs<=$offset){			$offset = $total_rs - $scale;		}		//scale 0 으로 지정시에는 전체 가져옴		if($scale > 0){			$sql .= " order by no, main, sub limit $offset,$scale ";		}else{			$sql .= " order by no, main, sub ";		}		$rs = mysqli_query($GLOBALS['dblink'], $sql);		//echo $sql;		// offset 을 이용한 limit 가 적용된 갯수		$total = mysqli_num_rows($rs);		$list['list']['total'] = $total;		// 페이지 네비게이션 오프셋 지정.		for($i=0; $i < $total; $i++){			$list['list'][$i] = mysqli_fetch_assoc($rs);			$m_cnt_row = mysqli_fetch_row(mysqli_query("select count(idx) from $tbl_comment WHERE boardid='$boardid' AND board_idx='".$list['list'][$i][idx]."' "));			$list['list'][$i][cmt_count] = $m_cnt_row[0];		}	}else{		$list['total'] = 0;	}	return $list;}//게시물 가져오기 - 파일 포함function getBoardListBaseNImage($boardid, $category, $sw="", $sk="", $scale, $offset=0){	//게시판 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	//카테고리가 있을경우	if($category !=""){		$que_category = " and A.category='$category' ";	}	//검색키워드가 있을경우	if($sk !=""){		switch($sw){			case("n") :				$que_where = "and A.name like '%$sk%'";				break;			case("s") :				$que_where = "and A.subject like '%$sk%'";				break;			case("c") :				$que_where = "and A.contents like '%$sk%'";				break;			case("e") :				$que_where = "and etc_1 = '$sk'";				break;			case("a") :			default :				$que_where = "and (A.name like '%$sk%' or A.subject like '%$sk%' or A.contents like '%$sk%')";		}		// 검색시 영역을 분할하여 검색=> 속도향상용		$sql = "select count(A.idx) as cnt from $tblid A";		$rs = mysqli_query($GLOBALS['dblink'], $sql);		$row = mysqli_fetch_assoc($rs);		$q_total = $row[cnt];		$q_start = $q_total - 10000; // 최근 10000건만 검색		if($q_total>10000){			$q_limit = " A.idx between " . $q_start . " and " . $q_total . " ";		}		// 검색시 영역을 분할하여 검색=> 속도향상용	}	//카운트//	$sql = "select count(A.idx) from $tblid A WHERE A.no='1' $q_limit $que_where $que_category ";	$sql = "select count(A.idx) from $tblid A WHERE 1=1 $q_limit $que_where $que_category ";	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$row = mysqli_fetch_row($rs);	$total_rs = $row[0];	//목록	$sql  = "SELECT A.*, B.idx AS f_idx, B.boardid, B.b_idx, B.ori_name, B.re_name, B.type, B.size ";	$sql .= "FROM $tblid A LEFT JOIN ".$GLOBALS["_conf_tbl"]["board_files"]." B ON B.boardid='$boardid' AND A.idx=B.b_idx AND B.ext IN('jpg','gif','png')";//    $sql .= "WHERE A.no='1' $q_limit $que_where $que_category group by A.idx";	$sql .= "WHERE 1=1 $q_limit $que_where $que_category group by A.idx";	//echo $sql;	if($total_rs > 0){		$list['total'] = $total_rs;		// 페이지 네비게이션 오프셋 지정.		if(!$offset){			$offset=0;		}else{			$offset=$offset;		}		// offset 이 전체 게시물수보다 작을때 offset 을 전체게시물 - 페이지당 보여줄 글 수로 offset 설정		if($total_rs<=$offset){			$offset = $total_rs - $scale;		}		//scale 0 으로 지정시에는 전체 가져옴		if($scale > 0){			$sql .= " order by A.no, A.main, A.sub limit $offset,$scale ";		}else{			$sql .= " order by A.no, A.main, A.sub ";		}		$rs = mysqli_query($GLOBALS['dblink'], $sql);		// offset 을 이용한 limit 가 적용된 갯수		$total = mysqli_num_rows($rs);		$list['list']['total'] = $total;		// 페이지 네비게이션 오프셋 지정.		for($i=0; $i < $total; $i++){			$list['list'][$i] = mysqli_fetch_assoc($rs);		}	}else{		$list['total'] = 0;	}	return $list;}//게시물 등록하기function insertBoardArticle($boardid, $thumwidth){	$sub_sql= "";	$hit = $_POST['hit']??0;	$contents = mysqli_real_escape_string($GLOBALS['dblink'], $_POST['contents'])??"";	$contents = str_replace("'","’",$contents);	$subject = mysqli_real_escape_string($GLOBALS['dblink'], $_POST['subject'])??"";	$subject = str_replace("'","’",$subject);	if(!isset($_POST["is_notice"])){	$_POST["is_notice"]=""; }	//게시판 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	//main 번호 가져오기	$q_main = mysqli_query($GLOBALS['dblink'],"select min(main) from $tblid ");	$c_main = @mysqli_result($q_main,0,0);	if(!$c_main){		$main='99999999';	}else{		$main=$c_main-1;	}	//게시판 공지 설정	if(mysqli_real_escape_string($GLOBALS['dblink'], $_POST['is_notice'])=="Y"){		$setNo = "0";	}else{		$setNo = "1";	}	if(isset($_POST['schedule_date'])) {		$sql_add = " schedule_date='".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['schedule_date'])."', ";	} else {		$sql_add = " schedule_date=Curdate(), ";	}	$sql_add .= " wdate=now() ";	//게시판 테이블에 입력	if(!isset($_POST['usereplyemail'])){	$_POST['usereplyemail'] = "N"; }	if(!isset($_POST['usehtml'])){	$_POST['usehtml'] = "N"; }	if(!isset($_POST['uselock'])){	$_POST['uselock'] = "N"; }	$etc_2 = mysqli_real_escape_string($GLOBALS['dblink'], postNullCheck('etc_2'));	$etc_3 = mysqli_real_escape_string($GLOBALS['dblink'], postNullCheck('etc_3'));	$etc_4 = mysqli_real_escape_string($GLOBALS['dblink'], postNullCheck('etc_4'));	$etc_5 = mysqli_real_escape_string($GLOBALS['dblink'], postNullCheck('etc_5'));	$pass = "";	if(isset($_POST['pass'])){		$pass = mysqli_real_escape_string($GLOBALS['dblink'], $_POST['pass']) ;	## 비밀번호 있을 경우 단방향 암호화	}	$tel = "";	if(isset($_POST['tel'])){		$tel = mysqli_real_escape_string($GLOBALS['dblink'], $_POST['tel']) ;	## 연락처	}	$email = "";	if($_POST['email']){		$email =  mysqli_real_escape_string($GLOBALS['dblink'], $_POST['email']);	##	}else{		$email =  mysqli_real_escape_string($GLOBALS['dblink'], $_POST['email1'])."@".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['email2']) ;	##	}	$category = "";	if (is_array($someVariable) || $someVariable instanceof Countable) {		$count = count($someVariable);	} else {		$count = 0;	}	############################################ 주안영상미디어센터 ############################################ ST	if($boardid == "edu"){		$days = "";		for($i=0;$i<count($_POST['days']);$i++){			$days	.= $comma.$_POST['days'][$i];			$comma = "|";		}		$edu_no = mysqli_fetch_assoc(mysqli_query($GLOBALS['dblink'],"SELECT IFNULL(MAX(edu_no), 0) + 1 AS next_no FROM tbl_board_edu"))['next_no'];		$sub_sql = "							reception_status = '".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['reception_status'])."',					category1 = '".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['cat1'])."',			category2 = '".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['cat2'])."',				education_name = '".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['education_name'])."',			r_start_date = '".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['r_start_date'])."',			r_end_date = '".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['r_end_date'])."',			e_start_date = '".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['e_start_date'])."',			e_end_date = '".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['e_end_date'])."',			day_type = '".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['day_type'])."',			days='".$days."',			start_hour = '".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['start_hour'])."',			start_minute = '".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['start_minute'])."',			end_hour = '".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['end_hour'])."',			end_minute = '".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['end_minute'])."',									thumbnail = '".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['thumbnail'])."',			instructor = '".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['instructor'])."',						curriculum = '".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['curriculum'])."',			remarks = '".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['remarks'])."',					capacity = '".mysqli_real_escape_string($GLOBALS['dblink'], empty($_POST['capacity']) ? '0' : $_POST