ink'], $_POST['board_type'])."',		proof_type = '".mysqli_real_escape_string($GLOBALS['dblink'],"현금")."',						finalamount = '".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['finalamount'])."',				deposit_date = '".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['deposit_date'])."',     		deposit_status = '".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['deposit_status'])."',		p_idx = '" . mysqli_real_escape_string($GLOBALS['dblink'], empty($_POST['idx']) ? '0' : $_POST['idx']) . "',	";}if ($boardid == "payment_details") {	if ($_POST['board_type'] =="equ"){		$eatblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . "equ_applicants";		$usage_people = mysqli_fetch_assoc(mysqli_query($GLOBALS['dblink'],"SELECT usage_people FROM $eatblid WHERE idx = '".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['type_idx'])."'"))['usage_people'];		$usage_day = mysqli_fetch_assoc(mysqli_query($GLOBALS['dblink'],"SELECT usage_day FROM $eatblid WHERE idx = '".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['type_idx'])."'"))['usage_day'];	}	else if($_POST['board_type'] =="place"){		$patblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . "place_applicants";		$usage_time = mysqli_fetch_assoc(mysqli_query($GLOBALS['dblink'],"SELECT usage_time FROM $patblid WHERE idx = '".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['type_idx'])."'"))['usage_time'];	}	$sub_sql .= "		board_type = '".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['board_type'])."',		discount_text = '" . mysqli_real_escape_string($GLOBALS['dblink'], $_POST['discount_text']) . "',		discount = '" . mysqli_real_escape_string($GLOBALS['dblink'], $_POST['discount']) . "',		discountamount = '" . mysqli_real_escape_string($GLOBALS['dblink'], $_POST['discountamount']) . "',		finalamount = '".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['finalamount'])."',			deposit_status = '" . mysqli_real_escape_string($GLOBALS['dblink'], $_POST['deposit_status']) . "',		deposit_date = '" 