Perm = true;	}	//기존정보와 비밀번호를 비교	$arrArticleInfo = getArticleInfo($tblid, $idx);	if($arrArticleInfo["list"][0]["pass"] && ($arrArticleInfo["list"][0]["pass"]==trim($_POST['pass']) || password_verify(trim($_POST['pass']), $arrArticleInfo["list"][0]["pass"]))){		//	$modifyPerm = true;	//비밀번호 입력형식이면	}	// 본인아이디 확인	// 로그인 상태이고 로그인 아이디와 글 쓴 아이디가 같을 경우	if($_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["MEMBER"]["ID"]==$arrArticleInfo["list"][0]["w_user"]){		$modifyPerm = true;	}	// 기업회원	if($_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["MEMBER"]["ID"]==$arrArticleInfo["list"][0]["registration"]){		$modifyPerm = true;	}	// 관람객	if($_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["MEMBER"]["ID"]==$arrArticleInfo["list"][0]["email"]){		$modifyPerm = true;	}	//권한받은자만 젒근	if($_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["ADMIN"]["GRADE"]=="ACCEL" && @in_array("biz_manage",$_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["ADMIN"]["AUTH"])){		$modifyPerm = true;	}	//게시판 공지 설정	if($_POST['is_notice']=="Y"){		$setNo = "0";	}else{		$setNo = "1";	}	if($modifyPerm==true){		//게시판 테이블 지정		$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;		if(isset($_POST['hit'])) {			$sql_add = " hit=".$_POST['hit'].", ";		}		if(isset($_POST['schedule_date'])) {			$sql_add .= " schedule_date='".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['schedule_date'])."', ";		} else {			//	$sql_add .= " schedule_date=Curdate(), ";		}		/*		if(isset($_POST['wdate'])) {			$sql_add .= " wdate='".$_POST['wdate']."' ";		} else {			$sql_add .= " wdate=now() ";		}*/		$etc_2 = mysqli_real_escape_string($GLOBALS['dblink'], postNullCheck('etc_2'));		$etc_3 = mysqli_real_escape_string($GLOBALS['dblink'], postNullCheck('etc_3'));		$etc_4 = mysqli_real_escape_string($GLOBALS['dblink'], postNullCheck('etc_4'));		$etc_5 = mysqli_real_escape_string($GLOBALS['dblink'], postNullCheck('etc_5'));		$tel = "";		if(isset($_POST['tel'])){			$tel = mysqli_real_escape_string($GLOBALS['dblink'], $_POST['tel']) ;