 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	//main 번호 가져오기	$q_main = mysqli_query("select main,sub,depth,email,usereplyemail,pass,uselock,no from ".$tblid." where idx = '".$idx."'", $GLOBALS['dblink']);	$row = mysqli_fetch_array($q_main);	$c_main =					$row[0];	$c_sub =						$row[1];	$c_depth =					$row[2];	$c_email =					$row[3];	$c_usereplyemail =		$row[4];	$c_pass =						$row[5];	$c_lock =						$row[6];	$c_no =						$row[7];	if($c_no=="0"){		jsMsg("공지글에는 답글을 달 수 없습니다.");		return false;	}	//잠긴글에 답글을 달 경우 원 사용자가 볼수 있게 비밀번호를 원 글의 비밀번호로 입력	if($c_lock =="Y"){		$pass = $c_pass;		$uselock = "Y";	}else{		$pass = mysql_escape_string($_POST[pass]);		$uselock = mysql_escape_string($_POST[uselock]=="Y"?"Y":"N");	}	$main = $c_main;	$sub = $c_sub + 1;	$depth = $c_depth + 1;	mysqli_query("UPDATE ".$tblid." set sub=sub+1 where no='1' and main='$main' and sub>'$c_sub'", $GLOBALS['dblink']);	if($_POST[wdate]) {		$sql_add = " wdate='".mysql_escape_string($_POST[wdate])."' ";	} else {		$sql_add = " wdate=now() ";	}	//게시판 테이블에 입력	$sql = "INSERT INTO ".$tblid." set 		no='1',		main='$main',		sub='$sub',		depth='$depth',		w_user='".$_POST['w_user_id']."',		r_user='".$_POST['r_user_id']."',		name='".mysql_escape_string($_POST['name'])."',		pass='".$pass."',		homepage='".mysql_escape_string($_POST['homepage'])."',		email='".mysql_escape_string($_POST['email'])."',		subject='".mysql_escape_string(str_replace("\"","'",$_POST['subject']))."',		contents='".mysql_escape_string($_POST['contents'])."',		usereplyemail='".mysql_escape_string($_POST['usereplyemail']=="Y"?"Y":"N")."',		usehtml='".mysql_escape_string($_POST['usehtml']=="Y"?"Y":"N")."',		category='".mysql_escape_string($_POST['category'])."',		uselock='".$uselock."',		hit='0',		etc_1='".mysql_escape_string($_POST['etc_1'])."',		etc_2='".mysql_escape_string($_POST['etc_2'])."',		etc_3='".mysql_escape_string($_POST['etc_3'])."',		etc_4='".mysql_escape_string($_POST['etc_4'])."',		etc_5='".mysql_escape_string($_POST['etc_5'])."',		ip='".$_SERVER['REMOTE_ADDR']."',		$sql_add	";	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$insert_idx = mysqli_insert_id($GLOBALS['dblink']);	$total = mysqli_affected_rows($GLOBALS['dblink']);	//파일처리	if($_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["ADMIN"]["ID"]) {		inputBoardFiles($boardid, $insert_idx, $_FILES, $thumwidth);	}	if($total > 0){		// 글 등록시 메일링여부		if ($c_usereplyemail=='Y'){			if($_POST['usehtml'] !='Y') $contents = nl2br($_POST['contents']);			mailing($GLOBALS["_SITE"]["NAME"],$GLOBALS["_SITE"]["EMAIL"],$c_email,$_POST[subject],$contents);		}		return true;	}else{		return false;	}}function cancelBoardArticle($boardid, $idx){	//게시판 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	$sql = "UPDATE ".$tblid." set category='4', time='' 			WHERE idx='".$idx."'		";	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$total = mysqli_affected_rows($GLOBALS['dblink']);	if($total > 0){		return true;	}else{		return false;	}}//게시물 삭제하기function deleteBoardArticle($boardid, $idx, $pass){	//게시판 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	$tbl_comment = $GLOBALS["_conf_tbl"]["comment"];	$tbl_board_product = $GLOBALS["_conf_tbl"]["board_product"];	//삭제권한 설정	$deletePerm = false;	//관리자는 그냥 통과	if($_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["ADMIN"]["GRADE"]=="ROOT" || @in_array("board_manage",$_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["ADMIN"]["AUTH"])){		$deletePerm = true;	}	//기존정보와 비밀번호를 비교 - 수정할때와 다른 함수를 씀 (파일 삭제 때문에)	$arrArticleInfo = getBoardArticleView($boardid, $category, $idx, "delete");	if($arrArticleInfo["list"][0]["pass"]==trim($pass) || password_verify(trim($pass), $arrArticleInfo["list"][0]["pass"])){		$deletePerm = true;	}	// 로그인 상태이고 로그인 아이디와 글 쓴 아이디가 같을 경우	if($_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["MEMBER"]["ID"]==$arrArticleInfo["list"][0]["r_user"]){		$deletePerm = true;	}	if($deletePerm==true){		//게시판 테이블 지정		$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;		//게시판 테이블에서 삭제		$sql = "DELETE FROM ".$tblid." 			WHERE idx='".$idx."'		";		$rs = mysqli_query($GLOBALS['dblink'], $sql);		$total = mysqli_affected_rows($GLOBALS['dblink']);		//파일삭제 코딩 시작		for($i=0;$i<$arrArticleInfo["total_files"];$i++){			//디비에서 파일정보 삭제			mysqli_query("DELETE FROM ".$GLOBALS["_conf_tbl"]["board_files"]." WHERE boardid='".$boardid."' AND idx='".$arrArticleInfo["files"][$i]['idx']."' ", $GLOBALS['dblink']);			//디스크에서 파일 삭제			@unlink($GLOBALS["_SITE"]["BOARD_DATA"] . "/".$boardid."/".$arrArticleInfo["files"][$i]['re_name']);			//썸네일 삭제			if($arrArticleInfo["files"][$i]["type"]=="image/pjpeg" || $arrArticleInfo["files"][$i]["type"]=="image/x-png" || $arrArticleInfo["files"][$i]["type"]=="image/jpeg" || $arrArticleInfo["files"][$i]["type"]=="image/png" || $arrArticleInfo["files"][$i]["type"]=="image/gif"){				@unlink($GLOBALS["_SITE"]["BOARD_DATA"] . "/".$boardid."/t_".$arrArticleInfo["files"][$i]['re_name']);			}		}		//파일삭제 코딩 종료		//댓글 삭제		//mysqli_query("DELETE FROM ".$tbl_comment." WHERE boardid='".$boardid."' AND board_idx='".$idx."' ", $GLOBALS['dblink']);		//메인 event		if($boardid == "event1" || $boardid == "event2") {			mysqli_query("DELETE FROM tbl_board_tmp WHERE boardid='".$boardid."' AND b_idx='".$idx."' ", $GLOBALS['dblink']);		}		if($total > 0){			return true;		}else{			return false;		}	}else{		jsMsg("비밀번호가 일치하지 않습니다.");		return false;	}}//관리자 게시물 삭제시function deleteBoardAdmin($boardid, $idx){	//게시판 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	$tbl_comment = $GLOBALS["_conf_tbl"]["comment"];	$tbl_board_product = $GLOBALS["_conf_tbl"]["board_product"];	//삭제권한 설정	$deletePerm = false;	//관리자는 그냥 통과	if($_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["ADMIN"]["GRADE"]=="ROOT" || @in_array("board_manage",$_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["ADMIN"]["AUTH"])){		$deletePerm = true;	}	$arrArticleInfo = getBoardArticleView($boardid, $category, $idx, "delete");	if($arrArticleInfo["list"][0]["w_user"]==trim($_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["MEMBER"]["ID"])){		$deletePerm = true;	}	if($deletePerm==true){		//게시판 테이블 지정		$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;		//게시판 테이블에서 삭제		$sql = "DELETE FROM ".$tblid." WHERE idx in (".$idx.")";		$rs = mysqli_query($GLOBALS['dblink'], $sql);		$total = mysqli_affected_rows($GLOBALS['dblink']);		if( $boardid=="ktoabiz" ){			$sql_ktoaresults = "";			$sql_ktoaresults = "DELETE FROM tbl_board_ktoaresults WHERE biz_idx in (".$idx.")";			$rs = mysqli_query($GLOBALS['dblink'], $sql_ktoaresults);		}		if($total > 0){			return true;		}else{			return false;		}	}else{		return false;	}}function bestBoardUp($sid, $idx){	$sql  = "SELECT etc_5 FROM tbl_board_after WHERE idx in (".$idx.") and etc_5 like '%". $sid ."%'";	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$total_rs = mysqli_num_rows($rs);	if($total_rs < 1){		$sql = "update tbl_board_after set etc_5 = CONCAT(etc_5, ',". $sid ."')  WHERE idx in (".$idx.")";		$rs = mysqli_query($GLOBALS['dblink'], $sql);		return true;	}else{		return false;	}}//관리자 게시물 삭제시function updownBoardAdmin($boardid, $main, $updown){	//게시판 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	$sql  = "SELECT * ";	$sql .= "FROM $tblid ";	$sql .= "WHERE main = '$main' ";	$rs = mysqli_query($GLOBALS['dblink'], $sql);	//echo $sql;	$total_rs = mysqli_num_rows($rs);	if($total_rs > 0){		for($i=0; $i < $total_rs; $i++){			$list['list'][$i] = mysqli_fetch_assoc($rs);		}	}	if($updown=="up"){		$sql  = "SELECT * FROM $tblid WHERE main > '$main' order by main asc limit 0,1 ";		$rs = mysqli_query($GLOBALS['dblink'], $sql);		$total_rs = mysqli_num_rows($rs);		if($total_rs > 0){			$row = mysqli_fetch_assoc($rs);			$sql = "update ".$tblid." set main='$main' WHERE idx in (".$row["idx"].")";			//echo $sql;			$rs = mysqli_query($GLOBALS['dblink'], $sql);			$sql = "update ".$tblid." set main='".$row["main"]."' WHERE idx in (".$list['list'][0]["idx"].")";			$rs = mysqli_query($GLOBALS['dblink'], $sql);		}	}else{		$sql  = "SELECT * FROM $tblid WHERE main < '$main' order by main desc limit 0,1 ";		$rs = mysqli_query($GLOBALS['dblink'], $sql);		$total_rs = mysqli_num_rows($rs);		if($total_rs > 0){			$row = mysqli_fetch_assoc($rs);			$sql = "update ".$tblid." set main='$main' WHERE idx in (".$row["idx"].")";			$rs = mysqli_query($GLOBALS['dblink'], $sql);			$sql = "update ".$tblid." set main='".$row["main"]."' WHERE idx in (".$list['list'][0]["idx"].")";			$rs = mysqli_query($GLOBALS['dblink'], $sql);		}	}	if($total_rs > 0){		return true;	}else{		return false;	}}//3년 지난 게시물 삭제하기function deleteBoardArticle3YearsAgo($boardid){	//게시판 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	$tbl_comment = $GLOBALS["_conf_tbl"]["comment"];	$tbl_board_product = $GLOBALS["_conf_tbl"]["board_product"];	//삭제권한 설정	$deletePerm = true;	//관리자는 그냥 통과	//if($_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["ADMIN"]["GRADE"]=="ROOT" || @in_array("board_manage",$_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["ADMIN"]["AUTH"])){	//$deletePerm = true;	//}	if($deletePerm==true){		//게시판 테이블 지정		$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;		$sqlWhere = " WHERE DATE_FORMAT(wdate,'%Y-%m-%d') < DATE_FORMAT(DATE_ADD(NOW(), INTERVAL -3 YEAR),'%Y-%m-%d');";		//게시판 테이블에서 삭제		$sql = "DELETE FROM tbl_board_mindconsult".$sqlWhere;		$rs = mysqli_query($GLOBALS['dblink'], $sql);		$total = mysqli_affected_rows($GLOBALS['dblink']);		$sql = "DELETE FROM tbl_board_mindqna".$sqlWhere;		$rs = mysqli_query($GLOBALS['dblink'], $sql);		$total = $total+mysqli_affected_rows($GLOBALS['dblink']);		$sql = "DELETE FROM tbl_board_mindmtapp".$sqlWhere;		$rs = mysqli_query($GLOBALS['dblink'], $sql);		$total = $total+mysqli_affected_rows($GLOBALS['dblink']);		$sql = "DELETE FROM tbl_board_mindvisit".$sqlWhere;		$rs = mysqli_query($GLOBALS['dblink'], $sql);		$total = $total+mysqli_affected_rows($GLOBALS['dblink']);		$sql = "DELETE FROM tbl_board_mindvolunteer".$sqlWhere;		$rs = mysqli_query($GLOBALS['dblink'], $sql);		$total = $total+mysqli_affected_rows($GLOBALS['dblink']);		$sql = "DELETE FROM tbl_board_mindcheck".$sqlWhere;		$rs = mysqli_query($GLOBALS['dblink'], $sql);		$total = $total+mysqli_affected_rows($GLOBALS['dblink']);		if($total > 0){			return $total;		}else{			return "0";		}	}else{		jsMsg("권한이 없습니다.");		return false;	}}//게시물 가져오기 - idfunction getBoardArticleView($boardid, $category, $idx, $mode="read", $subQuery = ""){	//게시판 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	$que_category = "";	//카테고리가 있을경우	if($category !=""){		$que_category = " and category in ('$category') ";	}	$que_category .= $subQuery;	//조회수 먼저 업데이트	if($mode=="read"){		$sql  = "UPDATE $tblid SET ";		$sql .= " hit = hit + 1 ";		$sql .= "WHERE idx = '".$idx."' $que_category ";		$rs = mysqli_query($GLOBALS['dblink'], $sql);	}	$sql  = "SELECT * ";	$sql .= "FROM $tblid ";	if($idx){		$sql .= "WHERE idx = '".$idx."' ".$que_category;	}else{		$sql .= "WHERE " .  $que_category;	}	$rs = mysqli_query($GLOBALS['dblink'], $sql);//	echo "echo:"; print_r($sql); echo "<br>" ;	$total_rs = mysqli_num_rows($rs);	if($total_rs > 0){		$list['total'] = $total_rs;		for($i=0; $i < $total_rs; $i++){			$list['list'][$i] = mysqli_fetch_assoc($rs);			//html 사용여부 체크-> 읽기 페이지에서만			if($mode=="read" && $list['list'][$i]['usehtml']!='Y'){				$list['list'][$i]['contents'] = nl2br(htmlspecialchars($list['list'][$i]['contents']));			}			$b_sort = $list['list'][$i]['b_sort'];		}	}else{		$list['total'] = 0;	}	//이전글, 다음글은 읽기 모드일때만	if($mode=="read"){		//이전글 정보 가져오기		if($b_sort){	## 리스트 정렬사용시			$sql = "SELECT max(b_sort) FROM $tblid WHERE b_sort < '$b_sort' $que_category";		}else{			$sql = "SELECT max(idx) FROM $tblid WHERE idx < '$idx' $que_category";		}		//	echo $sql;		$rs = mysqli_query($GLOBALS['dblink'], $sql);		$prev = mysqli_result($rs,0,0);		if($prev > -1){			$list["prev"]["idx"] = $prev;			if($b_sort){	## 리스트 정렬사용시				$sql = "SELECT idx, name, subject, hit, wdate FROM $tblid WHERE b_sort = '$prev' $que_category";			}else{				$sql = "SELECT idx, name, subject, hit, wdate FROM $tblid WHERE idx = '$prev' $que_category ";			}			//	echo $sql;			$rs = mysqli_query($GLOBALS['dblink'], $sql);			$list["prev"] = mysqli_fetch_assoc($rs);		}else{			$list["prev"]["idx"] = 0;		}		//다음글 정보 가져오기		if($b_sort){	## 리스트 정렬사용시			$sql = "SELECT min(b_sort) FROM $tblid WHERE b_sort > '$b_sort' $que_category";		}else{			$sql = "SELECT min(idx) FROM $tblid WHERE idx > '$idx' $que_category";		}		$rs = mysqli_query($GLOBALS['dblink'], $sql);		$next = mysqli_result($rs,0,0);		if($next > 0){			$list["next"]["idx"] = $next;			if($b_sort){	## 리스트 정렬사용시				$sql = "SELECT idx, name, subject, hit, wdate FROM $tblid WHERE b_sort = '$next' $que_category";			}else{				$sql = "SELECT idx, name, subject, hit, wdate FROM $tblid WHERE idx = '$next' $que_category ";			}			$rs = mysqli_query($GLOBALS['dblink'], $sql);			$list["next"] = mysqli_fetch_assoc($rs);		}else{			$list["next"]["idx"] = 0;		}	}	//파일정보 가져오기	$sql  = "SELECT * ";	$sql .= "FROM ".$GLOBALS["_conf_tbl"]["board_files"]." ";	$sql .= "WHERE boardid = '$boardid' ";	//$sql .= "AND b_idx = '$idx' AND LEFT(re_name,1) <> 'l' order by idx";	$sql .= "AND b_idx = '$idx' order by idx";	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$total_rs = mysqli_num_rows($rs);	if($total_rs > 0){		$list['total_files'] = $total_rs;		for($i=0; $i < $total_rs; $i++){			$list['files'][$i] = mysqli_fetch_assoc($rs);		}	}else{		$list['total_files'] = 0;	}	return $list;}//게시물 가져오기 - nofunction getBoardViewNo($boardid, $category, $idx, $mode="read"){	//게시판 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	$que_category = "";	//카테고리가 있을경우	if($category !=""){		$que_category = " and category in ($category) ";	}	$sql  = "SELECT * ";	$sql .= "FROM $tblid ";	$sql .= "WHERE main = '".$idx."' ".$que_category;	$rs = mysqli_query($GLOBALS['dblink'], $sql);	//echo $sql;	$total_rs = mysqli_num_rows($rs);	if($total_rs > 0){		$list['total'] = $total_rs;		for($i=0; $i < $total_rs; $i++){			$list['list'][$i] = mysqli_fetch_assoc($rs);			//html 사용여부 체크-> 읽기 페이지에서만			if($mode=="read" && $list['list'][$i]['usehtml']!='Y'){				$list['list'][$i]['contents'] = nl2br(htmlspecialchars($list['list'][$i]['contents']));			}		}	}else{		$list['total'] = 0;	}	return $list;}//글잠금 해제function unlockBoardArticle($boardid, $idx, $pass){	//게시판 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	$sql  = "SELECT * ";	$sql .= "FROM $tblid ";	$sql .= "WHERE idx = '$idx'";	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$list['list'][0] = mysqli_fetch_assoc($rs);	if(password_verify($pass, $list["list"][0]["pass"]) || $pass == $list["list"][0]["pass"]){		return true;	}else{		return false;	}}//파일정보 가져오기function getArticleFileListInfo($boardid, $b_idx){	$sql  = "SELECT * ";	$sql .= "FROM " .$GLOBALS["_conf_tbl"]["board_files"]." ";	$sql .= "WHERE boardid = '$boardid' ";	$sql .= "AND b_idx = '$b_idx' ";//	echo $sql;	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$total_rs = mysqli_num_rows($rs);	if($total_rs > 0){		$list['total'] = $total_rs;		for($i=0; $i < $total_rs; $i++){			$list['list'][$i] = mysqli_fetch_assoc($rs);		}	}else{		$list['total'] = 0;	}	return $list;}//파일정보 가져오기function getArticleFileInfo($boardid, $b_idx, $idx){	$sql  = "SELECT * ";	$sql .= "FROM " .$GLOBALS["_conf_tbl"]["board_files"]." ";	$sql .= "WHERE boardid = '$boardid' ";	$sql .= "AND b_idx = '$b_idx' ";	$sql .= "AND idx = '$idx' ";//	echo $sql;	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$total_rs = mysqli_num_rows($rs);	if($total_rs > 0){		$list['total'] = $total_rs;		for($i=0; $i < $total_rs; $i++){			$list['list'][$i] = mysqli_fetch_assoc($rs);		}	}else{		$list['total'] = 0;	}	return $list;}//파일정보 가져오기function getArticleFileInfoImage($boardid, $idx){	$sql  = "SELECT * ";	$sql .= "FROM " .$GLOBALS["_conf_tbl"]["board_files"]." ";	$sql .= "WHERE boardid = '$boardid' ";	$sql .= "AND idx = '$idx' ";//	echo $sql;	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$total_rs = mysqli_num_rows($rs);	if($total_rs > 0){		$list['total'] = $total_rs;		for($i=0; $i < $total_rs; $i++){			$list['list'][$i] = mysqli_fetch_assoc($rs);		}	}else{		$list['total'] = 0;	}	return $list;}//최근게시물 목록 가져오기function getBoardMember($boardid){	//게시판 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	$sql = "SELECT distinct subject FROM $tblid order by subject desc";	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$total = mysqli_num_rows($rs);	if($total > 0){		$list['total'] = $total;		$rs = mysqli_query($GLOBALS['dblink'], $sql);		for($i=0; $i < $total; $i++){			$list['list'][$i] = mysqli_fetch_assoc($rs);		}	}else{		$list['total'] = 0;	}	return $list;}//게시판 파일처리## function inputBoardFiles($boardid, $idx, $_FILES, $thumwidth){function inputBoardFiles($boardid, $idx, $tmp, $thumwidth){	if($boardid=="accept"){	//		########################################################### 멀티 파일 업로드 ########################################################### ST		$photo		= $_FILES['upfiles'];		$uploadDir	= $GLOBALS["_SITE"]["BOARD_DATA"] . "/".$boardid."/";		$fileName	= $photo['name'];		$tmpName	= $photo['tmp_name'];		$filesize	= $photo['size'];		$filetype	= $photo['type'];		//var_dump($photo);		//exit;		for($i=0; $i<count($fileName); $i++){			$memo			= $_POST["memo"];			$tmpFilename	= $fileName[$i];			$attach_ext		= explode(".",$tmpFilename);			$extension		= $attach_ext[sizeof($attach_ext)-1];			$extension		= strtolower($extension);			$fileRename		= $memo."_".md5(mktime()).$i.".".$extension;			if (is_uploaded_file($tmpName[$i])) {				move_uploaded_file($tmpName[$i], $uploadDir.$fileRename); // 디렉토리에 저장하기				$sql = "insert into ".$GLOBALS["_conf_tbl"]["board_files"]." set 					boardid='".$boardid."',/*게시판 아이디*/					b_idx='".$idx."',/* 글 번호 id*/					ori_name='".$fileName[$i]."',/*파일원본이름*/					re_name='".$fileRename."',/*md5로 변환된 파일이름*/					type='".$filetype[$i]."',/*파일타입*/					ext ='".$extension."',/*파일확장자*/					size='".$filesize[$i]."',/*첨부파일 용량*/					wdate=now()				";				$rsf = mysqli_query($GLOBALS['dblink'], $sql);			}		}		########################################################### 멀티 파일 업로드 ########################################################### ED	}else{		for($i=0;$i<count($_FILES['upfiles']['error']);$i++){			if ($_FILES['upfiles']['error'][$i] == 0){				//확장자 검사후 파일이름 생성				if(isset($_POST['memo_name'][$i])){					$memo = $_POST['memo_name'][$i];				}else{					$memo = "";				}				$filename = $_FILES['upfiles']['name'][$i];				$attach_ext = explode(".",$filename);				$extension = $attach_ext[sizeof($attach_ext)-1];				$extension = strtolower($extension);				$filerename = $memo."_".md5(mktime()) . $i . "." . $extension;				$filesize = $_FILES['upfiles']['size'][$i];				$filetype = $_FILES['upfiles']['type'][$i];				// 파일 확장자 검사				if(!strcmp($extension,"htm") ||!strcmp($extension,"html") ||!strcmp($extension,"phtml") ||!strcmp($extension,"php") ||!strcmp($extension,"php3") ||!strcmp($extension,"php4") ||!strcmp($extension,"inc") ||!strcmp($extension,"pl") ||!strcmp($extension,"cgi")){					jsMsg("not allowed file extension");					jsHistory("-1");				}				if (is_uploaded_file($_FILES['upfiles']['tmp_name'][$i])) {					move_uploaded_file ($_FILES['upfiles']['tmp_name'][$i], $GLOBALS["_SITE"]["BOARD_DATA"] . "/".$boardid."/".$filerename);					//썸네일 만들기					if($filetype=="image/pjpeg" || $filetype=="image/x-png" || $filetype=="image/jpeg" || $filetype=="image/png" || $filetype=="image/gif"){						@MakeThum($GLOBALS["_SITE"]["BOARD_DATA"] . "/".$boardid."/".$filerename, $GLOBALS["_SITE"]["BOARD_DATA"] . "/".$boardid."/t_".$filerename, $thumwidth);					}				}				$sql = "insert into ".$GLOBALS["_conf_tbl"]["board_files"]." set 					boardid='".$boardid."',/*게시판 아이디*/					b_idx='".$idx."',/* 글 번호 id*/					ori_name='".$filename."',/*파일원본이름*/					re_name='".$filerename."',/*md5로 변환된 파일이름*/					type='".$filetype."',/*파일타입*/					ext ='".$extension."',/*파일확장자*/					size='".$filesize."',/*첨부파일 용량*/					wdate=now()				";				$rsf = mysqli_query($GLOBALS['dblink'], $sql);			}		}	}}//댓글 목록 가져오기function getCommentList($boardid, $board_idx, $scale, $offset2=0, $page=""){	// 테이블 지정	$tbl = $GLOBALS["_conf_tbl"]["comment"];	$sql = "SELECT * FROM $tbl WHERE 1=1 ";	if($boardid !=""){		$sql .= " AND boardid='$boardid' ";	}	if($board_idx !=""){		$sql .= " AND board_idx='$board_idx' ";	}	if($page == "admin") {		$sql .= " order by idx desc ";	} else {		$sql .= " order by idx desc ";	}	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$total_rs = mysqli_num_rows($rs);	//echo $sql;	if($total_rs > 0){		$list['total'] = $total_rs;		// 페이지 네비게이션 오프셋 지정.		if(!$offset2){			$offset2=0;		}else{			$offset2=$offset2;		}		// offset 이 전체 게시물수보다 작을때 offset 을 전체게시물 - 페이지당 보여줄 글 수로 offset 설정		if($total_rs<=$offset2){			$offset2 = $total_rs - $scale;		}		//scale 0 으로 지정시에는 전체 가져옴		if($scale > 0){			$sql .= " limit $offset2, $scale ";		}		$rs = mysqli_query($GLOBALS['dblink'], $sql);		// offset 을 이용한 limit 가 적용된 갯수		$total = mysqli_num_rows($rs);		$list['list']['total'] = $total;		// 페이지 네비게이션 오프셋 지정.		for($i=0; $i < $total; $i++){			$list['list'][$i] = mysqli_fetch_assoc($rs);		}	}else{		$list['total'] = 0;	}	return $list;}//댓글 등록하기function insertComment($boardid, $board_idx){	// 테이블 지정	$tbl = $GLOBALS["_conf_tbl"]["comment"];	if($_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["ADMIN"]["ID"]) {		$user_id = $_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["ADMIN"]["ID"];		$user_name = $GLOBALS["_SITE"]["NAME"];	} else {		$user_id = $_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["MEMBER"]["ID"];		$user_name = $_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["MEMBER"]["NAME"];	}	$user_id = $_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["MEMBER"]["ID"];	$user_name = $_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["MEMBER"]["NAME"];	//$arrInfo = getBoardArticleView($boardid, "", $board_idx, "comment");	$grpno = 1;	if($_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["ADMIN"]["ID"] || $_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["MEMBER"]["ID"]) {		//댓글 테이블에 입력		$sql = "INSERT INTO ".$tbl." set 			boardid='$boardid',			board_idx='$board_idx',			prino='".$grpno."',			user_id='".$user_id."',			user_name='".$user_name."',			comment='".strip_tags($_POST['comment'])."',			ip='".$_SERVER['REMOTE_ADDR']."',			wdate=now()		";		//echo $sql;		$rs = mysqli_query($GLOBALS['dblink'], $sql);		$insert_idx = mysqli_insert_id($GLOBALS['dblink']);	}	$total = mysqli_affected_rows($GLOBALS['dblink']);	if($total > 0){		return true;	}else{		return false;	}}//댓글 수정하기function updateComment($boardid, $board_idx, $idx){	// 테이블 지정	$tbl = $GLOBALS["_conf_tbl"]["comment"];	//댓글 테이블에 입력	$sql = "UPDATE ".$tbl." set 		comment='".mysql_escape_string($_POST[comment])."',		ip='".$_SERVER[REMOTE_ADDR]."'		Where boardid='$boardid' and board_idx='$board_idx' and idx='".$idx."'	";	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$total = mysqli_affected_rows($GLOBALS['dblink']);	if($total > 0){		return true;	}else{		return false;	}}//댓글에 댓글 등록하기function replyComment($boardid, $board_idx, $idx){	// 테이블 지정	$tbl = $GLOBALS["_conf_tbl"]["comment"];	if($_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["ADMIN"]["ID"]) {		$user_id = $_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["ADMIN"]["ID"];		$user_name = $GLOBALS["_SITE"]["NAME"];	} else {		$user_id = $_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["MEMBER"]["ID"];		$user_name = $_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["MEMBER"]["NICK"]?$_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["MEMBER"]["NICK"]:$_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["MEMBER"]["NAME"];	}	$sql = "select prino,depno from ".$tbl." where idx='$idx'";	$result = mysqli_query($sql) or error(mysqli_error());	$row = mysqli_fetch_array($result);	$prino = $row[prino];	$depno = ++$row[depno];	$sql = "update ".$tbl." set prino = prino+1 where boardid='$boardid' and board_idx='$board_idx' and prino >= '$prino'";	$result = mysqli_query($GLOBALS['dblink'], $sql);	//댓글 테이블에 입력	$sql = "INSERT INTO ".$tbl." set 		boardid='$boardid',		board_idx='$board_idx',		prino='".$prino."',		depno='".$depno."',		user_id='".$user_id."',		user_name='".$user_name."',		comment='".mysql_escape_string($_POST[comment])."',		ip='".$_SERVER[REMOTE_ADDR]."',		wdate=now()	";	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$total = mysqli_affected_rows($GLOBALS['dblink']);	if($total > 0){		return true;	}else{		return false;	}}//댓글 가져오기 - idfunction getCommentInfo($idx){	// 테이블 지정	$tbl = $GLOBALS["_conf_tbl"]["comment"];	$sql  = "SELECT * ";	$sql .= "FROM $tbl ";	$sql .= "WHERE idx = '$idx' ";	$rs = mysqli_query($GLOBALS['dblink'], $sql);	//echo $sql;	$total_rs = mysqli_num_rows($rs);	if($total_rs > 0){		$list['total'] = $total_rs;		for($i=0; $i < $total_rs; $i++){			$list['list'][$i] = mysqli_fetch_assoc($rs);		}	}else{		$list['total'] = 0;	}	return $list;}//댓글 삭제하기function deleteComment($idx){	// 테이블 지정	$tbl = $GLOBALS["_conf_tbl"]["comment"];	//삭제권한 설정	$deletePerm = false;	//관리자는 그냥 통과	if($_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["ADMIN"]["GRADE"]=="ROOT" || @in_array("board_manage",$_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["ADMIN"]["AUTH"])){		$deletePerm = true;	}	//기존정보	$arrArticleInfo = getCommentInfo($idx);	if($arrArticleInfo["list"][0]["user_id"]==$_SESSION[$GLOBALS["_SITE"]["DOMAIN"]]["MEMBER"]["ID"]){		$deletePerm = true;	}	if($deletePerm==true){		//댓글 테이블에서 삭제		$sql = "DELETE FROM ".$tbl." 			WHERE idx='$idx'		";		$rs = mysqli_query($GLOBALS['dblink'], $sql);		$total = mysqli_affected_rows($GLOBALS['dblink']);		if($total > 0){			return true;		}else{			return false;		}	}else{		// jsMsg("삭제할 권한이 없습니다.");		return false;	}}//==================================================// 첫화면 인텍스 메인화면에 리스트와 이미지 부르기// 200900604//===================================================function getBoardLastNImage($boardid, $limit,$category=""){	//게시판 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	//카테고리가 있을경우	if($category !=""){		$que_category = " and A.category='$category' ";	}	//목록	$sql  = "SELECT A.*, B.idx AS f_idx, B.boardid, B.b_idx, B.ori_name, B.re_name, B.type, B.size ";	$sql .= "FROM $tblid A LEFT JOIN ".$GLOBALS["_conf_tbl"]["board_files"]." B ON B.boardid='$boardid' AND A.idx=B.b_idx AND B.ext IN('jpg','gif','png')";	$sql .= "WHERE A.no='1' $que_where $que_category group by A.idx DESC LIMIT $limit";	$rs = mysqli_query($GLOBALS['dblink'], $sql);	// offset 을 이용한 limit 가 적용된 갯수	$total = mysqli_num_rows($rs);	$list['list']['total'] = $total;	// 페이지 네비게이션 오프셋 지정.	if($total > 0){		$list['total'] = $total;		// 페이지 네비게이션 오프셋 지정.		for($i=0; $i < $total; $i++){			$list['list'][$i] = mysqli_fetch_assoc($rs);		}	}else{		$list['total'] = 0;	}	return $list;}//==============================================// 게시물 첨부파일,메모카운트// 20090507// 첨부파일조인후 메모카운트는 배열에 추가저장// 피노갤러리에서 가져옴//==============================================function getBoardListBaseNFileNMemoCnt($boardid, $category, $sw="", $sk="", $scale, $offset=0){	//게시판 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	// 추가부분	// 코멘트 테이블	$tbl_comment = $GLOBALS["_conf_tbl"]["comment"];	//카테고리가 있을경우	if($category !=""){		$que_category = " and A.category='$category' ";	}	//검색키워드가 있을경우	if($sk !=""){		switch($sw){			case("n") :				$que_where = "and A.name like '%$sk%'";				break;			case("s") :				$que_where = "and A.subject like '%$sk%'";				break;			case("c") :				$que_where = "and A.contents like '%$sk%'";				break;			case("ltdNm") :				$que_where = "and A.etc_7 like '%$sk%'";				break;			case("a") :			default :				$que_where = "and (A.name like '%$sk%' or A.subject like '%$sk%' or A.contents like '%$sk%')";		}		// 검색시 영역을 분할하여 검색=> 속도향상용		$sql = "select count(A.idx) as cnt from $tblid A";		$rs = mysqli_query($GLOBALS['dblink'], $sql);		$row = mysqli_fetch_assoc($rs);		$q_total = $row[cnt];		$q_start = $q_total - 10000; // 최근 10000건만 검색		if($q_total>10000){			$q_limit = " A.idx between " . $q_start . " and " . $q_total . " ";		}		// 검색시 영역을 분할하여 검색=> 속도향상용	}	//카운트	$sql = "select count(A.idx) from $tblid A WHERE A.no='1' $q_limit $que_where $que_category ";	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$row = mysqli_fetch_row($rs);	$total_rs = $row[0];	//목록	$sql  = "SELECT A.*, B.idx AS f_idx, B.boardid, B.b_idx, B.ori_name, B.re_name, B.type, B.size ";	$sql .= "FROM $tblid A LEFT JOIN ".$GLOBALS["_conf_tbl"]["board_files"]." B ON B.boardid='$boardid' AND A.idx=B.b_idx ";	$sql .= "WHERE A.no='1' $q_limit $que_where $que_category group by A.idx";	if($total_rs > 0){		$list['total'] = $total_rs;		// 페이지 네비게이션 오프셋 지정.		if(!$offset){			$offset=0;		}else{			$offset=$offset;		}		// offset 이 전체 게시물수보다 작을때 offset 을 전체게시물 - 페이지당 보여줄 글 수로 offset 설정		if($total_rs<=$offset){			$offset = $total_rs - $scale;		}		//scale 0 으로 지정시에는 전체 가져옴		if($scale > 0){			$sql .= " order by A.main limit $offset,$scale ";		}else{			$sql .= " order by A.main ";		}		$rs = mysqli_query($GLOBALS['dblink'], $sql);		// offset 을 이용한 limit 가 적용된 갯수		$total = mysqli_num_rows($rs);		$list['list']['total'] = $total;		// 페이지 네비게이션 오프셋 지정.		for($i=0; $i < $total; $i++){			$list['list'][$i] = mysqli_fetch_assoc($rs);			// 댓글 카운트 추가 부분			$m_cnt_row = mysqli_fetch_row(mysqli_query("select count(idx) from $tbl_comment WHERE boardid='$boardid' AND board_idx='".$list['list'][$i][idx]."' "));			$list['list'][$i][cmt_count] = $m_cnt_row[0];		}	}else{		$list['total'] = 0;	}	return $list;}//easyUi json Listfunction getJsonList($boardid, $scale, $offset=0, $orderby="", $wheresql=""){	//게시판 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	if($orderby){		$ordersql = $orderby;	}else{		$ordersql = "order by main desc" ;	}	$sql = "SELECT * FROM $tblid $wheresql $ordersql";	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$total_rs = mysqli_num_rows($rs);	if($total_rs > 0){		$list['total'] = $total_rs;		// 페이지 네비게이션 오프셋 지정.		if(!$offset){			$offset=0;		}else{			$offset=$offset;		}		// offset 이 전체 게시물수보다 작을때 offset 을 전체게시물 - 페이지당 보여줄 글 수로 offset 설정		if($total_rs<=$offset){			$offset = $total_rs - $scale;		}		//scale 0 으로 지정시에는 전체 가져옴		if($scale > 0){			$sql .= " limit $offset,$scale ";		}		$rs = mysqli_query($GLOBALS['dblink'], $sql);		// offset 을 이용한 limit 가 적용된 갯수		$total = mysqli_num_rows($rs);//			echo $sql;		//$list['row']['total'] = $total;		// 페이지 네비게이션 오프셋 지정.		for($i=0; $i < $total; $i++){			$list['rows'][$i] = mysqli_fetch_assoc($rs);			$list['rows'][$i]["rownum"] = $total_rs-$i-$offset;		}	}else{		$list['total'] = 0;	}	return $list;}//easyUi json Listfunction getJsonListFile($boardid, $scale, $offset=0, $orderby="", $wheresql=""){	//게시판 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	if($orderby){		$ordersql = $orderby;	}else{		$ordersql = "order by A.idx desc" ;	}	$sql = "SELECT * FROM $tblid AS A $wheresql $ordersql";	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$total_rs = mysqli_num_rows($rs);	$sub_query = $GLOBALS["_conf_tbl"]["board_files"];	$sql  = " SELECT A.*, B.idx AS f_idx, B.boardid, B.b_idx, B.ori_name, B.re_name, B.type, B.size ";	$sql .= " FROM $tblid A LEFT JOIN ".$sub_query." B ON B.boardid='$boardid' AND A.idx=B.b_idx ";	$sql .= " $wheresql group by A.idx";	if($total_rs > 0){		$list['total'] = $total_rs;		// 페이지 네비게이션 오프셋 지정.		if(!$offset){			$offset=0;		}else{			$offset=$offset;		}		// offset 이 전체 게시물수보다 작을때 offset 을 전체게시물 - 페이지당 보여줄 글 수로 offset 설정		if($total_rs<=$offset){			$offset = $total_rs - $scale;		}		//scale 0 으로 지정시에는 전체 가져옴		if($scale > 0){			$sql .= " order by A.no, A.main, A.sub limit $offset,$scale ";		}else{			$sql .= " order by A.no, A.main, A.sub ";		}		$rs = mysqli_query($GLOBALS['dblink'], $sql);		// offset 을 이용한 limit 가 적용된 갯수		$total = mysqli_num_rows($rs);//			echo $sql;		//$list['row']['total'] = $total;		// 페이지 네비게이션 오프셋 지정.		for($i=0; $i < $total; $i++){			$list['rows'][$i] = mysqli_fetch_assoc($rs);			$list['rows'][$i]["rownum"] = $total_rs-$i-$offset;		}	}else{		$list['total'] = 0;	}	return $list;}//easyUi json List - 온라인 문의function getJsonListOnline($boardid, $scale, $offset=0, $orderby="", $wheresql=""){	//게시판 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	if($orderby){		$ordersql = $orderby;	}else{		$ordersql = "order by idx desc" ;	}	$sql = "SELECT * FROM $tblid $wheresql $ordersql";	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$total_rs = mysqli_num_rows($rs);	if($total_rs > 0){		$list['total'] = $total_rs;		// 페이지 네비게이션 오프셋 지정.		if(!$offset){			$offset=0;		}else{			$offset=$offset;		}		// offset 이 전체 게시물수보다 작을때 offset 을 전체게시물 - 페이지당 보여줄 글 수로 offset 설정		if($total_rs<=$offset){			$offset = $total_rs - $scale;		}		//scale 0 으로 지정시에는 전체 가져옴		if($scale > 0){			$sql .= " limit $offset,$scale ";		}		$rs = mysqli_query($GLOBALS['dblink'], $sql);		// offset 을 이용한 limit 가 적용된 갯수		$total = mysqli_num_rows($rs);//			echo $sql;		//$list['row']['total'] = $total;		// 페이지 네비게이션 오프셋 지정.		for($i=0; $i < $total; $i++){			$list['rows'][$i] = mysqli_fetch_assoc($rs);			$list['rows'][$i]["rownum"] = $total_rs-$i-$offset;			if($list['rows'][$i]["etc_1"]=="Y"){				$list['rows'][$i]["etc_1"]="상담완료";			}else{				$list['rows'][$i]["etc_1"]="상담대기";			}			$list['rows'][$i]["etc_2"]=str_replace("||",", &nbsp;",$list['rows'][$i]["etc_2"]);			$list['rows'][$i]["etc_2"]=str_replace("|","",$list['rows'][$i]["etc_2"]);		}	}else{		$list['total'] = 0;	}	return $list;}########################################################### 이벤트// 등록하기function insertTarot($boardid, $sid, $tca, $tcaval){	// 테이블 지정	$tbl = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	$sql = "	INSERT INTO ".$tbl." set 		subject='".$sid."',		".$tca."='".$tcaval."',		ip='".$_SERVER['REMOTE_ADDR']."',		wdate=now()	";	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$insert_idx = mysqli_insert_id($GLOBALS['dblink']);	$total = mysqli_affected_rows($GLOBALS['dblink']);	if($total > 0){		return true;	}else{		return false;	}}//댓글 수정하기function updateTarot($boardid, $sid, $tca, $tcaval){	// 테이블 지정	$tbl = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	//댓글 테이블에 입력	$sql = "UPDATE ".$tbl." set 		".$tca."='".$tcaval."',		ip='".$_SERVER['REMOTE_ADDR']."'		Where subject='".$sid."'	";	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$total = mysqli_affected_rows($GLOBALS['dblink']);	if($total > 0){		return true;	}else{		return false;	}}################################################## 엑셀 다운로드용function getXlsList($boardid,  $sw="", $sk="", $scale, $offset2=0){	// 테이블 지정	$tbl = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	$sql = "SELECT * FROM $tbl A  WHERE 1=1 ";	if($_REQUEST['s_date']){		$sql .= " AND wdate >= '".$_REQUEST['s_date']." 00:00:00' ";	}	if($_REQUEST['e_date']){		$sql .= " AND wdate <= '".$_REQUEST['e_date']." 23:59:59' ";	}	if($_GET['equ_idx']){		$que_where .= " and A.equ_idx='".$_GET['equ_idx']."' ";	}	if ($_GET['rental_start_date']){		$que_where .= " and rental_start_date >='".$_GET['rental_start_date']."' ";	}	if ($_GET['rental_end_date']){		$que_where .= " and rental_end_date <='".$_GET['rental_end_date']."' ";	}	if($_GET['cat_no']){		$que_etc .= " and (A.category1='".$_GET['cat_no']."' or A.category2='".$_GET['cat_no']."') ";	}	if($_GET['status']){		$que_etc .= " and A.status='".$_GET['status']."' ";	}	if($_GET['user_level']){		$que_etc .= " and A.user_level='".$_GET['user_level']."' ";	}	if($_GET['app_no']){		$que_where = " and A.app_no like '%{$_GET['app_no']}%'";	}	if($_GET['board_type']){		$que_where = " and A.board_type like '%{$_GET['board_type']}%'";	}	if($_GET['deposit_status']){		$que_where = " and A.deposit_status like '%{$_GET['deposit_status']}%'";	}	if($_GET['refund_status']){		$que_where = " and A.refund_status like '%{$_GET['refund_status']}%'";	}	if($_GET['rental_type']){		$que_where = " and A.rental_type like '%{$_GET['rental_type']}%'";	}if($sk !=""){	switch($sw) {		case("all") :			$que_where = "and (A.subject like '%$sk%' or A.name like '%$sk%' or A.w_user like '%$sk%' or A.tel like '%$sk%')";			break;		case("app_no") :			$que_where = "and A.app_no like '%$sk%'";			break;		case("subject") :			$que_where = "and A.subject like '%$sk%'";			break;		case("status") :			$que_where = "and A.status like '%$sk%'";			break;		case("n") :			$que_where = "and A.name like '%$sk%'";			break;		case("username") :			$que_where = "and (A.name like '%$sk%' or A.etc_2 like '%$sk%' or A.etc_3 like '%$sk%')";			break;		case("userid") :			$que_where = "and A.w_user like '%$sk%'";			break;		case("wuser") :			$que_where = "and A.w_user ='$sk' ";			break;		case("s") :			$que_where = "and A.subject like '%$sk%'";			break;		case("idx") :			$que_where = "and A.idx = '$sk'";			break;		case("sd") :			$que_where = "and A.schedule_date like '%$sk%'";			break;	}}	$sql .= "  $que_where ";	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$total_rs = mysqli_num_rows($rs);	//echo $sql;	if($total_rs > 0){		$list['total'] = $total_rs;		// 페이지 네비게이션 오프셋 지정.		if(!$offset2){			$offset2=0;		}else{			$offset2=$offset2;		}		// offset 이 전체 게시물수보다 작을때 offset 을 전체게시물 - 페이지당 보여줄 글 수로 offset 설정		if($total_rs<=$offset2){			$offset2 = $total_rs - $scale;		}		//scale 0 으로 지정시에는 전체 가져옴		if($scale > 0){			$sql .= " limit $offset2, $scale ";		}		$rs = mysqli_query($GLOBALS['dblink'], $sql);		// offset 을 이용한 limit 가 적용된 갯수		$total = mysqli_num_rows($rs);		$list['list']['total'] = $total;		// 페이지 네비게이션 오프셋 지정.		for($i=0; $i < $total; $i++){			$list['list'][$i] = mysqli_fetch_assoc($rs);		}	}else{		$list['total'] = 0;	}	return $list;}//예약시간 가져오기function getTimeTable($boardid, $category, $sdate="", $scale, $offset=0){	//게시판 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	//카테고리가 있을경우	if($category !=""){		$que_category = " and category='$category' ";	}	if($sdate){		$que_where = " and schedule_date='".$sdate."' ";	}	//	$q_limit = " and homepage='Y' ";	//카운트	$sql = "select count(idx) from $tblid WHERE 1=1 $q_limit $que_where $que_category ";	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$row = mysqli_fetch_row($rs);	$total_rs = $row[0];	//목록	$sql  = "SELECT idx,etc_1,etc_2,(select count(idx) from tbl_board_covid where time=a.idx) as tc ";	$sql .= "FROM $tblid as a ";	//$sql .= "WHERE no='1' $q_limit $que_where $que_category ";	$sql .= "WHERE 1=1 $q_limit $que_where $que_category ";	if($total_rs > 0){		$list['total'] = $total_rs;		// 페이지 네비게이션 오프셋 지정.		if(!$offset){			$offset=0;		}else{			$offset=$offset;		}		// offset 이 전체 게시물수보다 작을때 offset 을 전체게시물 - 페이지당 보여줄 글 수로 offset 설정		if($total_rs<=$offset){			$offset = $total_rs - $scale;		}		if($scale > 0){			$sql .= " order by etc_1 asc , etc_2 asc limit $offset,$scale ";		}else{			$sql .= " order by etc_1 asc , etc_2 asc ";		}		$rs = mysqli_query($GLOBALS['dblink'], $sql);		//echo $sql;		// offset 을 이용한 limit 가 적용된 갯수		$total = mysqli_num_rows($rs);		$list['list']['total'] = $total;		// 페이지 네비게이션 오프셋 지정.		for($i=0; $i < $total; $i++){			$list['list'][$i] = mysqli_fetch_assoc($rs);		}	}else{		$list['total'] = 0;	}	return $list;}///////////////////// 수강시간 입력 & 수정function studyUpdate($vodtype, $appidx, $durat, $curr, $userID, $pidx = "0"){	$sql = "select count(idx) AS CNT, MAX(curr) AS cTime, durat from tbl_board_study WHERE w_user ='" . $userID . "' AND category='" . $vodtype . "' AND appidx	='" . $appidx . "' ";	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$row = mysqli_fetch_row($rs);	$total_rs = $row[0];	if ($durat > 0) {	// insert		if ($row[0] < 1) {	//최초1회 입력			$sql = "			INSERT INTO tbl_board_study set				category='" . $vodtype . "',				appidx	='" . $appidx . "',				pidx	='" . $pidx . "',				durat	='" . $durat . "',				curr	='0',				w_user	='" . $userID . "',				wdate=now()			";			//echo $sql;			$rs = mysqli_query($GLOBALS['dblink'], $sql);			$total = mysqli_affected_rows($GLOBALS['dblink']);		}	} else {			// update		if ($row[1] < $curr) {	// 넘어온 시간보다 DB저장된 시간이 크면 저장안함			if ($row[2] < ($curr + 11)) {		// 최종시간보다 플레이시간이(+11) 크면 플레이시간을 최종시간으로 업데이트				$curr = $row[2];			}			$sql = "			UPDATE tbl_board_study set				curr	='" . $curr . "',				homepage = now()			WHERE w_user ='" . $userID . "' AND category='" . $vodtype . "' AND appidx	='" . $appidx . "'			";			//echo $sql;			$rs = mysqli_query($GLOBALS['dblink'], $sql);			$total = mysqli_affected_rows($GLOBALS['dblink']);			return true;		}	}}// 학습진척률function studyList($vodtype, $appidx, $userID){	$sql = "select curr,durat,homepage from tbl_board_study WHERE w_user ='" . $userID . "' AND category ='" . $vodtype . "' AND appidx in (" . $appidx . ") ";	$rs = mysqli_query($GLOBALS['dblink'], $sql);	// offset 을 이용한 limit 가 적용된 갯수	$total = mysqli_num_rows($rs);	$list['list']['total'] = $total;	// 페이지 네비게이션 오프셋 지정.	if ($total > 0) {		$list['total'] = $total;		// 페이지 네비게이션 오프셋 지정.		for ($i = 0; $i < $total; $i++) {			$list['list'][$i] = mysqli_fetch_assoc($rs);		}	} else {		$list['total'] = 0;		$list['list'][0]['curr'] = 0;		$list['list'][0]['durat'] = 0;	}	return $list;}//function getScheduleInsert($subject, $sdate, $subtitle=""){	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"]."schedule";	//main 번호 가져오기	$q_main = mysqli_query($GLOBALS['dblink'],"select min(main) from $tblid ");	$c_main = @mysqli_result($q_main,0,0);	if(!$c_main){		$main='99999999';	}else{		$main=$c_main-1;	}	$sql = "INSERT INTO ".$tblid." set 		no='1',		main='$main',		sub='0',		depth='0',		w_user='admin',		r_user='',		name='관리자',		pass='',		homepage='".$subtitle."',		tel='',		email='',		subject='".$subject."',		schedule_date='".$sdate."',				ip='".$_SERVER['REMOTE_ADDR']."',		wdate=now() ";	//echo $sql;	$rs = mysqli_query($GLOBALS['dblink'], $sql);	//$insert_idx = mysqli_insert_id($GLOBALS['dblink']);}// 결제정보 저장function setBoardOrderSave(){	$tbl_order_info = "tbl_board_accept";	$sql = "UPDATE ".$tbl_order_info." SET			order_state		='".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['order_state'])."',			ship_name		='".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['ship_name'])."',			ship_zip		='".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['ship_zip'])."',			ship_address	='".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['ship_address'])."',			ship_address_ext='".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['ship_address_ext'])."',			ship_phone		='".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['ship_phone'])."',						ship_note		='".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['ship_note'])."',						pay_type		='".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['pay_type'])."',			deposit_name	='".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['deposit_name'])."',			deposit_date	='".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['deposit_date'])."',			proof			='".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['proof'])."',			tax_registration='".mysqli_real_escape_string($GLOBALS['dblink'], $_POST['tax_registration