= '$sidx' ";	$sql .= "ORDER BY A.idx";	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$total_rs = mysqli_num_rows($rs);	$list = [];	if($total_rs > 0){		for($i=0; $i < $total_rs; $i++){			$list['list'][$i] = mysqli_fetch_assoc($rs);		}	}	// 파일 수 계산	$sql_files = "SELECT COUNT(*) as total_files FROM $fileDB WHERE boardid='$boardid' AND b_idx='$sidx'";	$rs_files = mysqli_query($GLOBALS['dblink'], $sql_files);	$row_files = mysqli_fetch_assoc($rs_files);	$list['total_files'] = $row_files['total_files'];	// 총 게시물 수 계산	$sql_total = "SELECT COUNT(*) as total FROM $tblid WHERE idx = '$sidx'";	$rs_total = mysqli_query($GLOBALS['dblink'], $sql_total);	$row_total = mysqli_fetch_assoc($rs_total);	$list['total'] = $row_total['total'];	return $list;}//신청 취소function modifyStatusCancel($boardid, $idx){	//게시판 테이블 지정	$tblid = $GLOBALS["_SITE"]["BOARD_PREWORD"] . $boardid;	$sql = "UPDATE ".$tblid." set 		status	='취소'		WHERE idx='".mysqli_real_escape_string($GLOBALS['dblink'], $idx)."'";	$rs = mysqli_query($GLOBALS['dblink'], $sql);	$total = mysqli_affected_rows($GLOBALS['dblink']);	if($rs){		return true;	}else{		return false;	}}?>